//! use aws_sdk_kms as kms;
//!
//! #[::tokio::main]
//! async fn main() -> Result<(), kms::Error> {
//!     let config = aws_config::load_from_env().await;
//!     let client = aws_sdk_kms::Client::new(&config);
//!
//!     // ... make some calls with the client
